/**
 * Pure logic that decides where a file generated by a webview is written in the workspace.
 *
 * Depends on nothing but the standard library and the shared DTOs; `WebviewBaseCommand` writes the files.
 */
import type { WriteFilesMessage } from '../../../../shared/extract-graphics/extract-graphics-dtos';
import { DEFAULT_ASSETS_GRAPHICS_PATH, DEFAULT_GRAPHICS_DATA_FOLDER_PATH } from '../../../../shared/zxide-project';

export type GeneratedFile = Pick<WriteFilesMessage['codeFiles'][number], 'fileType' | 'fileName'>;

export interface GeneratedFileTarget {
  /** Workspace folder the file is written under. */
  rootFolder: typeof DEFAULT_ASSETS_GRAPHICS_PATH | typeof DEFAULT_GRAPHICS_DATA_FOLDER_PATH;
  /** Path of the file inside `rootFolder`. */
  pathSegments: string[];
  isBinary: boolean;
}

/**
 * Resource files (`.cfg`, `.png`) live next to the source image under `assets/`.
 * Code files (`.h`, `.asm`, `.bin`) live under `src/data/`.
 */
function resolveGeneratedFileRoot(fileType: GeneratedFile['fileType']): GeneratedFileTarget['rootFolder'] {
  switch (fileType) {
    case 'map':
    case 'png':
      return DEFAULT_ASSETS_GRAPHICS_PATH;
    case 'c-header':
    case 'asm':
    case 'binary':
      return DEFAULT_GRAPHICS_DATA_FOLDER_PATH;
  }
}

/** Workspace location and write mode of a generated file. */
export function routeGeneratedFile(file: GeneratedFile): GeneratedFileTarget {
  return {
    rootFolder: resolveGeneratedFileRoot(file.fileType),
    pathSegments: splitWorkspaceRelativePath(file.fileName),
    isBinary: file.fileType === 'png' || file.fileType === 'binary',
  };
}

/**
 * Splits a workspace-relative path in segments. Backslashes count as separators; leading separators,
 * empty, `.` and `..` segments are dropped, so the result cannot leave the folder it is joined to.
 */
export function splitWorkspaceRelativePath(input: string): string[] {
  const normalised = input.replace(/\\/g, '/').replace(/^\/+/, '');
  return normalised.split('/').filter((segment) => segment.length > 0 && segment !== '.' && segment !== '..');
}
